    elif isinstance(value, str):
        kind, raw = "string", value
    elif isinstance(value, datetime):
        kind = "datetime" if value.tzinfo is not None else "datetime-local"
        raw = json.dumps(value.isoformat().replace("+00:00", "Z"))
    elif isinstance(value, date):
        kind, raw = "date-local", json.dumps(value.isoformat())
    elif isinstance(value, time):
        kind, raw = "time-local", json.dumps(value.isoformat())
    elif isinstance(value, list):
        return [tagged(item) for item in value]
    elif isinstance(value, dict):
        return {key: tagged(item) for key, item in value.items()}
    else:
        raise TypeError(type(value).__name__)
    return {"type": kind, "value": raw}


def float_text(value: float) -> str:
    """Use the compact decimal spelling emitted by Taplo's TOML decoder."""
    if value != value:
        return "nan"
    if value == float("inf"):
        return "inf"
    if value == float("-inf"):
        return "-inf"
    raw = repr(value)
    if "e" not in raw:
        return raw
    exponent = int(raw.split("e")[1])
    # Taplo uses fixed notation from 1e-5 through values below 1e16.
    if -5 <= exponent < 16:
        fixed = format(Decimal(raw), "f")
        return fixed if "." in fixed else fixed + ".0"
    mantissa = raw.split("e")[0]
    return f"{mantissa}e{exponent}"


def encode(document) -> str:
    """Encode an already parsed TOML document as compact toml-test JSON."""
    return json.dumps(tagged(document), ensure_ascii=False, separators=(",", ":"))
